test:stdout unbounded message
```

> since the "exception channel" is also used by the program under test which may catch the exceptions generated by failing assertions

Shouldn't test assertions *about* the program under test occur *outside* the program under test? Using your terminology, exceptions thrown within the program belong to the program's "exception channel", while those outside the program but within the wrapping test function belong to the test's exception channel, with any uncaught exceptions in the program's exception channel flowing out to the test's exception channel.

For example, compare the four tests in this modified version of your first example:
```js
import {test} from "node:test";
import assert from "node:assert";

function function_under_test(callback, value) {
    let r = 0;
    try {
        r = callback(value);
    } catch (error) {
       //log error...
    }
    if (r === undefined) throw 'POOF!'
    //continue executing operations...
}

test("test should PASS", function () {
    function_under_test(function (v) {
        assert.fail("BOOM!");
    }, 4);
});

test("test should FAIL", function () {
    function_under_test(function (v) {
        assert.fail("BOOM!");
    }, 4);
    assert.fail("BOOMERANG!");
});


test("test should FAIL", function () {
    function_under_test(function (v) {
        return undefined
    }, 4);
});

test("test should PASS", function () {
    assert.throws(
        function_under_test(function (v) {
            return undefined
        }, 4),
        '/POOF!/'
    );
});
```

Likewise, in your second example, why would `function_under_test`, presumably a black box meant to work outside of a testing context, reference `testContext`?

```js
test("weird test", function (testContext) {
    function_under_test(function (v) {
        testContext.assert.fail("BOOM!");
    }, 4);
});
```



