Our tick loop was running under node::CallbackScope

```
void OnTick() {
  v8::Locker locker(isolate);
  v8::Isolate::Scope isolateScope(isolate);
  v8::HandleScope handleScope(isolate);

  v8::Context::Scope scope(GetContext());

