```js
import { isMainThread } from 'node:worker_threads'
import { resolveObjectURL } from 'node:buffer'
import module from 'node:module'

/** @type {Map<string, Blob | PromiseWithResolvers<Blob>>} */
const map = new Map()

if (isMainThread) {
  const { port1, port2 } = new MessageChannel()

  module.registerHooks({
    resolve(specifier, context, nextResolve) {
      if (specifier.startsWith('blob:')) {
        const blob = resolveObjectURL(specifier)

        if (!['application/javascript', 'text/javascript'].includes(blob.type)) {
          throw new TypeError('Unsupported blob type: ' + blob.type + '. expected text/javascript MIME type.')
        }

        port1.postMessage({ blob, specifier })
      }
      return nextResolve(specifier, context, nextResolve)
    }
  })

  module.register(import.meta.url, {
    parentURL: import.meta.url,
    data: { port: port2 },
    transferList: [port2],
  })
}

async function resolve(specifier, context, nextResolve) {
  if (specifier.startsWith('blob:')) {
    return {
      url: specifier,
      shortCircuit: true,
      format: 'module',
    }
  }

  return nextResolve(specifier, context, nextResolve)
}

async function initialize({ port }) {
  port.addEventListener('message', evt => {
    const { blob, specifier } = evt.data
    const q = map.get(specifier)
    if (q) {
      q.resolve(blob)
    } else {
      map.set(specifier, blob)
    }
  })
  port.start()
}

async function load(specifier, context, nextLoad) {
  if (specifier.startsWith('blob:')) {
    let blob = map.get(specifier)

    if (!blob) {
      const q = Promise.withResolvers()
      map.set(specifier, q)
      blob = await q.promise
    }

    const source = await blob.text()
    map.delete(specifier)

    return {
      format: 'module',
      shortCircuit: true,
      source,
    }
  }

  return nextLoad(specifier, context, nextLoad)
}

export { initialize, load, resolve }
```

