FYI, it seems patching `dns.lookup` is a reliable workaround (especially if someone isn't lazy like me and doesn't use any), it affects net.connect, used by undici internally, which is what fetch() uses too.



```typescript
import dns from "node:dns";

const originalLookup = dns.lookup;

const patchedLookup: typeof dns.lookup = Object.assign(
  function(hostname: string, ...args: any[]) {
    const callback = args.length === 2 ? args[1] : args[0];
    const options = args.length === 2 ? args[0] : {};

    if (hostname.endsWith(".localhost") || hostname === "localhost") {
      const family = (typeof options === "number" ? options : options?.family) || 4;
      const address = family === 6 ? "::1" : "127.0.0.1";

      if (typeof options === "object" && options.all) {
        return process.nextTick(callback, null, [{ address, family }]);
      }

      return process.nextTick(
        callback,
        null,
        address,
        family,
      );
    }

    return (originalLookup as Function).call(null, hostname, ...args);
  } as typeof dns.lookup,
  { __promisify__: originalLookup.__promisify__ },
);

dns.lookup = patchedLookup;
```

