```ts
const { registerHooks, stripTypeScriptTypes } = require('node:module');

function load(url, context, nextLoad) {
   if (url.endsWith('.mts') || url.endsWith('.ts')) {
      const result = nextLoad(url, { ...context, format: 'module-typescript' });
      const out = stripTypeScriptTypes(result.source.toString());
      return { ...result, format: 'module', source: out };
   }
   return nextLoad(url, context);
}

if (__dirname.includes('node_modules')) {
   registerHooks({ load });
}
