This is a reasonable improvement, but not 100% correct. `.ts` files can still use CommonJS. The actual solution is to check the nearest `package.json` to make sure about CJS vs EMS.

```js
switch (extensionOfUrl) {
	case `cts`: {
		return loadForCommonjsTypeScript(url, context, nextLoad);
	}
	case `mts`: {
		return loadForModuleTypeScript(url, context, nextLoad);
	}
	case `ts`: {
		const typeOfModule = determineTypeOfModule(url); // package.json lookup happens here
		switch (typeOfModule) {
			case `commonjs`: {
				return loadForCommonjsTypeScript(
					url,
					context,
					nextLoad,
				);
			}
			case `module`: {
				return loadForModuleTypeScript(url, context, nextLoad);
			}
		}
	}
	default: {
		const output = nextLoad(url, context);
		return output;
	}
}
```
